Hotkey BuildHotkeyFromLowLevelEvent(WPARAM message, const KBDLLHOOKSTRUCT& info, AsyncKeyState getState)
{
    return {
        .win = IsDown(getState(VK_LWIN)) || IsDown(getState(VK_RWIN)),
        .ctrl = IsDown(getState(VK_CONTROL)),
        .shift = IsDown(getState(VK_SHIFT)),
        .alt = IsDown(getState(VK_MENU)) || (info.flags & LLKHF_ALTDOWN) || info.vkCode == VK_MENU,
        .key = static_cast<unsigned char>(info.vkCode)
    };
}

std::vector<HotkeyAction> matches;
{
    std::unique_lock lock{ mutex };
    const auto [first, last] = hotkeyDescriptors.equal_range({ .hotkey = hotkey });
    for (auto it = first; it != last; ++it)
        matches.push_back({ it->moduleName, it->action });
}
for (const auto& match : matches)
{
    if (match.action && match.action())
        return SuppressInvokedHotkey();
}
return CallNextHookEx(hHook, nCode, wParam, lParam);

const auto holdModifiers = ModifierMaskFromHotkey(m_nextHotkey);
const bool posted = HandleAltWindowCycleHotkey(true, holdModifiers);
if (!posted)
{
    Logger::warn("AltWindowCycle hotkey dispatch failed before reaching UI thread");
}
return posted;

if (!g_uiThread || g_shutdownRequested.load())
{
    Logger::warn("AltWindowCycle hotkey ignored because UI thread is not ready");
    return false;
}
if (!PostHotkeyToUIThread(forward, holdModifiers))
{
    Logger::warn("AltWindowCycle failed to post hotkey to UI thread: {}", GetLastError());
    return false;
}
return true;

TEST_METHOD(BuildHotkeyTreatsSysKeyAltFlagAsAlt)
{
    KBDLLHOOKSTRUCT info{ .vkCode = VK_OEM_3, .flags = LLKHF_ALTDOWN };
    const auto hotkey = BuildHotkeyForTest(WM_SYSKEYDOWN, info, AlwaysUp);
    Assert::IsTrue(hotkey.alt);
    Assert::AreEqual(static_cast<unsigned char>(VK_OEM_3), hotkey.key);
}
